def transform(grid):
    # ARC instances have a repeated background and a small encoded motif. In this
    # task, every singleton marker is expanded into a centered copy of the
    # contiguous three-cell motif embedded in the grid.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]

    motif = None
    for r in range(h):
        for c in range(w - 2):
            if all(grid[r][j] != bg for j in range(c, c + 3)):
                motif = grid[r][c:c + 3]
                break
        if motif is not None:
            break
    if motif is None:
        return out

    marker = next((value for row in grid for value in row
                   if value != bg and value not in motif), None)
    if marker is None:
        return out

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for k, value in enumerate(motif):
                    cc = c + k - 1
                    if 0 <= cc < w:
                        out[r][cc] = value
    return out

